import "aos/dist/aos.css";
import {
    FaFileSignature,
    FaBuilding,
    FaBalanceScale,
    FaHandshake,
    FaClipboardCheck,
    FaStamp,
    FaWhatsapp,
} from "react-icons/fa";

function Notary() {
    //-----------------------STATE VIEWS-----------------------//
    const notaryServices = [
        {
            title: "Deed of Establishment",
            description:
                "Preparation of company establishment deeds in accordance with applicable laws to ensure your business legality.",
            icon: FaBuilding,
        },
        {
            title: "Deed Amendment",
            description:
                "Official processing of amendments to articles of association and company data through a notarial deed.",
            icon: FaFileSignature,
        },
        {
            title: "Shareholder Agreement",
            description:
                "Drafting and legalization of shareholder agreements to ensure transparency and legal protection.",
            icon: FaHandshake,
        },
        {
            title: "Legalization & Waarmerking",
            description:
                "Legalization and registration of documents (waarmerking) to provide valid legal force.",
            icon: FaStamp,
        },
        {
            title: "Power of Attorney",
            description:
                "Preparation of legally valid power of attorney documents for business or personal purposes.",
            icon: FaClipboardCheck,
        },
        {
            title: "Legal Consultation",
            description:
                "Legal consultation services related to notarial matters and regulations to support your business legal certainty.",
            icon: FaBalanceScale,
        },
    ];

    const WA_NUMBER = "6281213094426";

    //------------------------FUNCTIONS------------------------//
    const getWaLink = (serviceName: string) => {
        const message = `Hello Regarde,%0AI would like to consult regarding the ${serviceName} service.%0APlease provide further information. Thank you.`;
        return `https://wa.me/${WA_NUMBER}?text=${message}`;
    };
    //------------------------FUNCTIONS------------------------//

    return (
        <div className="pt-24">
            {/* NOTARY DETAIL */}
            <section data-aos="zoom-out" className="pb-24 bg-white">
                <div className="w-11/12 md:w-8/12 mx-auto text-center">

                    {/* ICON */}
                    <div className="flex justify-center mb-6">
                        <div className="w-20 h-20 rounded-full bg-primary-blue-100 flex items-center justify-center">
                            <FaFileSignature className="text-primary-blue-700 text-4xl" />
                        </div>
                    </div>

                    {/* TITLE */}
                    <h2 className="text-4xl font-black text-primary-blue-900 mb-4">
                        Notary Services
                    </h2>

                    {/* DESCRIPTION */}
                    <p className="text-gray-600 max-w-2xl mx-auto mb-14">
                        Professional notary services to ensure legality,
                        legal certainty, and protection for every document
                        and business transaction.
                    </p>

                    {/* SUB SERVICES */}
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-8 text-left">
                        {notaryServices.map((service, i) => {
                            const Icon = service.icon;
                            return (
                                <div
                                    key={i}
                                    data-aos="fade-up"
                                    data-aos-delay={i * 100}
                                    className="bg-white rounded-xl border border-gray-200 p-6 hover:shadow-md transition flex flex-col"
                                >
                                    {/* CONTENT */}
                                    <div className="flex items-start gap-4">
                                        <div className="text-primary-blue-600 text-2xl mt-1">
                                            <Icon />
                                        </div>
                                        <div>
                                            <h3 className="font-semibold text-primary-blue-900">
                                                {service.title}
                                            </h3>
                                            <p className="text-sm text-gray-600 mt-1">
                                                {service.description}
                                            </p>
                                        </div>
                                    </div>

                                    {/* WA BUTTON */}
                                    <a
                                        href={getWaLink(service.title)}
                                        target="_blank"
                                        rel="noopener noreferrer"
                                        className="mt-auto self-end w-10 h-10 rounded-full bg-green-600 text-white flex items-center justify-center hover:bg-green-700 transition"
                                        aria-label="Chat via WhatsApp"
                                    >
                                        <FaWhatsapp className="text-lg" />
                                    </a>
                                </div>
                            );
                        })}
                    </div>
                </div>
            </section>
        </div>
    );
}

export default Notary;